# SPDX-License-Identifier: GPL-3.0-or-later
"""Script-generated Markdown and JSON case-table builder for ``#143``.

Produces deterministic, non-hand-typed case tables and headline summaries from
``case_manifest.toml``, ``known_gaps.toml``, and optional trajectory runs.
"""

from __future__ import annotations

import dataclasses
import json
import math
import pathlib
from typing import Any

from flexmesa.testing import (
    _case_verdict,
    artifact_compare,
    case_manifest,
    harness_runner,
    history_compare,
)

GENERATED_HEADER = (
    "<!-- GENERATED BY `flexmesa harness` (#143). DO NOT EDIT BY HAND. -->"
)

CONVECTIVE_CORE_FOCUS_CASES: frozenset[tuple[str, str]] = frozenset(
    {
        ("star", "hb_2M"),
        ("star", "16M_predictive_mix"),
        ("star", "16M_conv_premix"),
        ("star", "conv_core_cpm"),
        ("star", "semiconvection"),
        ("star", "1M_thermohaline"),
        ("star", "extended_convective_penetration"),
    }
)
MASS_LOSS_FOCUS_CASES: frozenset[tuple[str, str]] = frozenset(
    {
        ("star", "hot_cool_wind"),
        ("star", "high_mass"),
        ("star", "wd_nova_burst"),
        ("binary", "double_bh"),
    }
)
_STAR_MDOT_CANDIDATES: tuple[str, ...] = ("star_mdot", "log_abs_mdot")
_BINARY_MDOT_CANDIDATES: tuple[str, ...] = (
    "lg_mstar_dot_1",
    "lg_wind_mdot_1",
    "lg_mtransfer_rate",
)


def summarize_records(
    manifest: case_manifest.HarnessManifest,
    records: list[harness_runner.CaseHarnessRecord],
    known_gaps: dict[tuple[str, str], case_manifest.KnownGapSpec] | None = None,
    *,
    numerics_mode: str = "strict",
) -> dict[str, Any]:
    """Compute manifest-wide and run-level headline counts across ``records``.

    Args:
        manifest: Loaded ``HarnessManifest``.
        records: Evaluated ``CaseHarnessRecord`` sequence.
        known_gaps: Optional ``known_gaps.toml`` mapping for total gap count.
        numerics_mode: Arithmetic mode used for the run (``"strict"`` or
            ``"fast"``).

    Returns:
        Dictionary of headline counts and gate violation lists.
    """
    all_cases = manifest.cases
    by_suite = {
        s: sum(1 for c in all_cases if c.suite == s)
        for s in case_manifest.VALID_SUITES
    }
    n_ref_26 = sum(1 for c in all_cases if c.reference_status == "mesa_26_4_1")
    n_ref_interim = sum(
        1 for c in all_cases if c.reference_status == "interim_0b2e6bb"
    )
    n_ref_none = sum(
        1 for c in all_cases if c.reference_status == "no_reference_yet"
    )
    n_declared_gaps_total = (
        len(known_gaps)
        if known_gaps is not None
        else sum(1 for r in records if bool(r.known_gap_issue))
    )

    n_executed = sum(1 for r in records if r.executed)
    n_strict = sum(1 for r in records if r.executed and not r.controls_ignored)
    n_diag = sum(1 for r in records if r.executed and r.controls_ignored)
    n_term_ok = sum(
        1
        for r in records
        if r.executed and r.termination_matches and not r.controls_ignored
    )
    n_diag_term_ok = sum(
        1
        for r in records
        if r.executed and r.termination_matches and r.controls_ignored
    )
    n_strict_steps = sum(
        1
        for r in records
        if r.executed and not r.controls_ignored and r.steps > 0
    )
    n_diag_steps = sum(
        1 for r in records if r.executed and r.controls_ignored and r.steps > 0
    )
    n_pass_26 = sum(1 for r in records if r.verdict == "pass")
    n_interim_within = sum(
        1 for r in records if r.verdict == "interim reference (within tol)"
    )

    undeclared_failures = [
        f"{r.suite}/{r.case}" for r in records if r.is_undeclared_failure
    ]
    stale_known_gaps = [
        f"{r.suite}/{r.case} ({r.known_gap_issue})"
        for r in records
        if r.is_stale_known_gap
    ]

    return {
        "mesa_release": manifest.mesa_release,
        "zenodo_record": manifest.zenodo_record,
        "numerics_mode": numerics_mode,
        "total_cases": len(all_cases),
        "selected_cases": len(records),
        "cases_by_suite": by_suite,
        "reference_mesa_26_4_1": n_ref_26,
        "reference_interim_0b2e6bb": n_ref_interim,
        "reference_none_yet": n_ref_none,
        "executed_cases": n_executed,
        "strict_validated_cases": n_strict,
        "diagnostic_cases": n_diag,
        "strict_cases_taking_steps": n_strict_steps,
        "diagnostic_cases_taking_steps": n_diag_steps,
        "reaching_upstream_termination": n_term_ok,
        "diagnostic_reaching_upstream_termination": n_diag_term_ok,
        "passing_mesa_26_4_1": n_pass_26,
        "interim_within_tolerance": n_interim_within,
        "declared_known_gaps": n_declared_gaps_total,
        "undeclared_failures": undeclared_failures,
        "stale_known_gaps": stale_known_gaps,
        # Present only when a run reported stage step counts, so a summary
        # rebuilt from stored baseline rows is unchanged (DECISIONS #69).
        **(
            {
                "passes_with_step_count_differences": [
                    f"{r.suite}/{r.case}"
                    for r in records
                    if r.verdict == "pass" and r.step_count_differs
                ]
            }
            if any(r.stage_steps for r in records)
            else {}
        ),
    }


def record_to_dict(rec: harness_runner.CaseHarnessRecord) -> dict[str, Any]:
    """Convert a ``CaseHarnessRecord`` into a JSON-serializable dictionary.

    Args:
        rec: ``CaseHarnessRecord`` instance.

    Returns:
        JSON-serializable dictionary.
    """
    out: dict[str, Any] = {
        "suite": rec.suite,
        "case": rec.case,
        "reference_status": rec.reference_status,
        "reference_path": rec.reference_path,
        "required_termination": rec.required_termination,
        "verdict": rec.verdict,
        "executed": rec.executed,
        "run_status": rec.run_status,
        "observed_termination": rec.observed_termination,
        "termination_matches": rec.termination_matches,
        "steps": rec.steps,
        "retries": rec.retries,
        "iters": rec.iters,
        "mean_iters": rec.mean_iters,
        "mesa_steps": rec.mesa_steps,
        "mesa_retries": rec.mesa_retries,
        "mesa_iters": rec.mesa_iters,
        "mesa_mean_iters": rec.mesa_mean_iters,
        "mesa_iters_rows": rec.mesa_iters_rows,
        "wall_time_sec": round(rec.wall_time_sec, 4),
        "peak_rss_gb": round(rec.peak_rss_gb, 4),
        "known_gap_issue": rec.known_gap_issue,
        "known_gap_reason": rec.known_gap_reason,
        "is_undeclared_failure": rec.is_undeclared_failure,
        "is_stale_known_gap": rec.is_stale_known_gap,
        "controls_ignored": rec.controls_ignored,
        "n_controls_ignored": rec.n_controls_ignored,
        "strict_rejection": rec.strict_rejection,
        "comparison": (
            history_compare.comparison_to_dict(rec.comparison)
            if rec.comparison is not None
            else None
        ),
        "error_message": rec.error_message,
    }
    if rec.stage_steps or rec.mesa_stage_steps:
        # MESA's counts do not depend on how FlexMESA's run ended, so a row
        # whose run timed out, was rejected or errored still carries them.
        out["mesa_stage_steps"] = list(rec.mesa_stage_steps)
    if rec.stage_steps:
        out["stage_steps"] = list(rec.stage_steps)
        out["stage_step_deltas"] = [d.delta for d in rec.stage_step_deltas]
        out["step_count_differs"] = rec.step_count_differs
    if rec.component_comparisons:
        out["component_comparisons"] = {
            k: history_compare.comparison_to_dict(v)
            for k, v in rec.component_comparisons.items()
        }
    if rec.has_component_error:
        out["has_component_error"] = True
    if rec.artifact_comparison is not None:
        out["artifact_comparison"] = artifact_compare.comparison_to_dict(
            rec.artifact_comparison
        )
    return out


def build_report_payload(
    manifest: case_manifest.HarnessManifest,
    records: list[harness_runner.CaseHarnessRecord],
    known_gaps: dict[tuple[str, str], case_manifest.KnownGapSpec] | None = None,
    *,
    numerics_mode: str = "strict",
) -> dict[str, Any]:
    """Assemble the complete JSON report dictionary.

    Args:
        manifest: ``HarnessManifest`` instance.
        records: Sequence of ``CaseHarnessRecord`` entries.
        known_gaps: Optional ``known_gaps.toml`` mapping.
        numerics_mode: Arithmetic mode used for the run (``"strict"`` or
            ``"fast"``).

    Returns:
        Structured dictionary with ``summary`` and ``cases`` keys.
    """
    return {
        "summary": summarize_records(
            manifest, records, known_gaps, numerics_mode=numerics_mode
        ),
        "cases": [record_to_dict(r) for r in records],
    }


def default_baseline_json_path() -> pathlib.Path:
    """Return the committed MESA ``26.4.1`` baseline harness JSON path."""
    return (
        case_manifest.repo_root()
        / "benchmarks"
        / "history_harness"
        / "baseline_run_26_4_1.json"
    )


def build_deterministic_baseline_payload(
    manifest: case_manifest.HarnessManifest,
    records: list[harness_runner.CaseHarnessRecord],
    known_gaps: dict[tuple[str, str], case_manifest.KnownGapSpec] | None = None,
    *,
    numerics_mode: str = "strict",
) -> dict[str, Any]:
    """Build a deterministic baseline JSON payload omitting volatile timings.

    Args:
        manifest: ``HarnessManifest`` instance.
        records: Evaluated ``CaseHarnessRecord`` entries.
        known_gaps: Optional ``known_gaps.toml`` mapping.
        numerics_mode: Arithmetic mode used for the run (``"strict"`` or
            ``"fast"``).

    Returns:
        JSON-serializable dictionary with ``wall_time_sec`` and ``peak_rss_gb``
        normalized to ``0.0`` for deterministic git diffs.
    """
    normalized = [
        dataclasses.replace(r, wall_time_sec=0.0, peak_rss_gb=0.0)
        for r in records
    ]
    return build_report_payload(
        manifest, normalized, known_gaps, numerics_mode=numerics_mode
    )


def _find_track_dev(
    rec: harness_runner.CaseHarnessRecord,
    col: str,
) -> history_compare.TrackDeviation | None:
    if rec.comparison is None:
        return None
    for d in rec.comparison.track_deviations:
        if d.column == col:
            return d
    return None


def _fmt_signed_sci(val: float | None) -> str:
    if val is None:
        return "-"
    if not math.isfinite(val):
        return "non-finite"
    return f"{val:+.3e}"


def _fmt_abs_sci(val: float | None) -> str:
    if val is None:
        return "-"
    if not math.isfinite(val):
        return "non-finite"
    return f"{val:.3e}"


def _fmt_steps_pair(rec: harness_runner.CaseHarnessRecord) -> str:
    f_str = str(rec.steps) if rec.executed else "-"
    m_str = str(rec.mesa_steps) if rec.mesa_steps is not None else "-"
    if f_str == "-" and m_str == "-":
        return "-"
    return f"{f_str} ({m_str})"


def _fmt_retries_pair(rec: harness_runner.CaseHarnessRecord) -> str:
    f_str = str(rec.retries) if rec.executed else "-"
    m_str = str(rec.mesa_retries) if rec.mesa_retries is not None else "-"
    if f_str == "-" and m_str == "-":
        return "-"
    return f"{f_str} ({m_str})"


def _fmt_iters_pair(rec: harness_runner.CaseHarnessRecord) -> str:
    f_str = (
        f"{rec.mean_iters:.1f} [{rec.iters}]"
        if rec.executed and rec.iters is not None and rec.mean_iters is not None
        else "-"
    )
    if rec.mesa_iters is not None and rec.mesa_mean_iters is not None:
        if rec.mesa_steps is not None and rec.mesa_iters_rows == rec.mesa_steps:
            m_str = f"{rec.mesa_mean_iters:.1f} [{rec.mesa_iters}]"
        else:
            m_str = (
                f"{rec.mesa_mean_iters:.1f} "
                f"[{rec.mesa_iters}/{rec.mesa_iters_rows}r]"
            )
    else:
        m_str = "-"
    if f_str == "-" and m_str == "-":
        return "-"
    return f"{f_str} ({m_str})"


def _fmt_peak_rss(rec: harness_runner.CaseHarnessRecord) -> str:
    if (
        not rec.executed
        or not math.isfinite(rec.peak_rss_gb)
        or rec.peak_rss_gb <= 0.0
    ):
        return "-"
    return f"{rec.peak_rss_gb:.2f} GB"


def _fmt_num_zones_diff(rec: harness_runner.CaseHarnessRecord) -> str:
    dev = _find_track_dev(rec, "num_zones")
    if dev is not None:
        if not math.isfinite(dev.max_abs_diff):
            return "non-finite"
        abs_i = round(dev.max_abs_diff)
        if dev.max_rel_diff is not None and math.isfinite(dev.max_rel_diff):
            return f"{100.0 * dev.max_rel_diff:.2f}% ({abs_i})"
        return str(abs_i)
    if rec.comparison is not None and "num_zones" in rec.comparison.final_diffs:
        f_abs = rec.comparison.final_diffs["num_zones"]
        if not math.isfinite(f_abs):
            return "non-finite"
        if (
            rec.comparison.ref_span == 0.0
            and "rel_num_zones" in rec.comparison.final_diffs
        ):
            f_rel = rec.comparison.final_diffs["rel_num_zones"]
            if math.isfinite(f_rel):
                return f"{100.0 * abs(f_rel):.2f}% ({round(abs(f_abs))})"
        return f"final {round(f_abs):+d}"
    return "-"


def _fmt_max_dev(rec: harness_runner.CaseHarnessRecord) -> str:
    return _fmt_comparison_max_dev(rec.comparison)


def _fmt_comparison_max_dev(
    comp: history_compare.HistoryComparison | None,
) -> str:
    if comp is None or not comp.track_deviations:
        return "-"
    non_zone = [d for d in comp.track_deviations if d.column != "num_zones"]
    base_pool = non_zone if non_zone else list(comp.track_deviations)
    constrained = [d for d in base_pool if d.tolerance is not None]
    pool = constrained if constrained else base_pool
    worst = max(
        pool,
        key=lambda d: (
            float("inf") if math.isnan(d.max_abs_diff) else d.max_abs_diff
        ),
    )
    if not math.isfinite(worst.max_abs_diff):
        return f"`{worst.column}`: non-finite"
    return f"`{worst.column}`: {worst.max_abs_diff:.3e}"


def _render_convective_core_section(
    manifest: case_manifest.HarnessManifest,
    records: list[harness_runner.CaseHarnessRecord],
) -> list[str]:
    """Render mechanical ``mass_conv_core`` along-track comparisons (#155)."""
    by_key = manifest.by_key()
    selected = [
        rec
        for rec in records
        if (rec.suite, rec.case) in CONVECTIVE_CORE_FOCUS_CASES
        or "mass_conv_core" in by_key[(rec.suite, rec.case)].track_tolerances
        or "mass_conv_core" in by_key[(rec.suite, rec.case)].final_tolerances
    ]
    if not selected:
        return []
    out: list[str] = [
        "",
        "## Convective-Core Track Comparisons (`mass_conv_core`, `#155`)",
        "",
        "Generated mechanically from `baseline_run_26_4_1.json` / harness "
        "comparisons against MESA `26.4.1` stored reference histories. "
        "`mass_conv_core` values are in solar masses (`Msun`).",
        "",
        "| Suite | Case | Run Mode | Observed Term | Steps (MESA) | "
        "Final Coord Diff | `mass_conv_core` Final Diff (Msun) | "
        "`mass_conv_core` Max Track Diff (Msun) | "
        "`mass_conv_core` Median Track Diff (Msun) | Declared Gap |",
        "| :--- | :--- | :--- | :--- | ---: | ---: | ---: | ---: | ---: | "
        ":--- |",
    ]
    for rec in selected:
        obs_term = (
            f"`{rec.observed_termination}`" if rec.observed_termination else "-"
        )
        gap_str = rec.known_gap_issue if rec.known_gap_issue else "-"
        f_diff = (
            rec.comparison.final_diffs.get("mass_conv_core")
            if rec.comparison is not None
            else None
        )
        t_dev = _find_track_dev(rec, "mass_conv_core")
        out.append(
            f"| `{rec.suite}` | `{rec.case}` | {rec.run_mode} | {obs_term} | "
            f"{_fmt_steps_pair(rec)} | {_fmt_final_age_diff(rec)} | "
            f"{_fmt_signed_sci(f_diff)} | "
            f"{_fmt_abs_sci(t_dev.max_abs_diff if t_dev else None)} | "
            f"{_fmt_abs_sci(t_dev.median_abs_diff if t_dev else None)} | "
            f"{gap_str} |"
        )
    return out


def _pick_mass_loss_columns(
    rec: harness_runner.CaseHarnessRecord,
) -> tuple[str, str]:
    mass_col = "star_1_mass" if rec.suite == "binary" else "star_mass"
    candidates = (
        _BINARY_MDOT_CANDIDATES
        if rec.suite == "binary"
        else _STAR_MDOT_CANDIDATES
    )
    if rec.comparison is not None:
        dev_cols = {d.column for d in rec.comparison.track_deviations}
        fin_cols = set(rec.comparison.final_diffs)
        for cand in candidates:
            if cand in dev_cols or cand in fin_cols:
                return mass_col, cand
    return mass_col, candidates[0]


def _has_active_mass_loss_diff(rec: harness_runner.CaseHarnessRecord) -> bool:
    if not rec.executed or rec.comparison is None:
        return False
    mass_col, mdot_col = _pick_mass_loss_columns(rec)
    m_dev = _find_track_dev(rec, mass_col)
    if (
        m_dev is not None
        and math.isfinite(m_dev.max_abs_diff)
        and m_dev.max_abs_diff > 1.0e-12
    ):
        return True
    md_dev = _find_track_dev(rec, mdot_col)
    return bool(
        md_dev is not None
        and math.isfinite(md_dev.max_abs_diff)
        and md_dev.max_abs_diff > 1.0e-12
    )


def _render_search_track_section(
    records: list[harness_runner.CaseHarnessRecord],
) -> list[str]:
    """Render per-track ``astero`` search comparisons (``#430``)."""
    selected = [
        rec
        for rec in records
        if rec.suite == "astero"
        and any(k.startswith("track_") for k in rec.component_comparisons)
    ]
    if not selected:
        return []
    out: list[str] = [
        "",
        "## Astero Search Track Comparisons (`#430`)",
        "",
        "MESA's `astero` search evolves one track per objective evaluation "
        "and keeps only the last one in `LOGS/history.data`, so each "
        "FlexMESA track is compared with the MESA `26.4.1` track of the same "
        "number. `prefix` marks the last track of an unfinished run, "
        "compared with the MESA track up to the same `star_age`. A case "
        "passes only when it ran as many tracks as MESA, reached upstream's "
        "termination, and every track is within the manifest tolerances.",
        "",
        "| Suite | Case | Track | Kind | Rows (MESA) | First Div Step | "
        "Max Track Diff | Within Tol |",
        "| :--- | :--- | ---: | :--- | ---: | ---: | :--- | :--- |",
    ]
    for rec in selected:
        for key in sorted(rec.component_comparisons):
            if not key.startswith("track_"):
                continue
            comp = rec.component_comparisons[key]
            is_prefix = key.endswith(_case_verdict.TRACK_PREFIX_SUFFIX)
            track_no = int(key.split("_")[1])
            first_div = (
                str(comp.first_diverging_step)
                if comp.first_diverging_step is not None
                else "-"
            )
            within = (
                "yes"
                if comp.within_final_tolerances and comp.within_track_tolerances
                else "no"
            )
            out.append(
                f"| `{rec.suite}` | `{rec.case}` | {track_no} | "
                f"{'prefix' if is_prefix else 'full'} | "
                f"{comp.run_rows} ({comp.ref_rows}) | {first_div} | "
                f"{_fmt_comparison_max_dev(comp)} | {within} |"
            )
    return out


def _render_mass_loss_section(
    records: list[harness_runner.CaseHarnessRecord],
) -> list[str]:
    """Render mechanical ``star_mass`` and ``mdot`` track comparisons (#159)."""
    selected = [
        rec
        for rec in records
        if (rec.suite, rec.case) in MASS_LOSS_FOCUS_CASES
        or _has_active_mass_loss_diff(rec)
    ]
    if not selected:
        return []
    out: list[str] = [
        "",
        "## Mass-Loss Track Comparisons (`star_mass` and `mdot`, `#159`)",
        "",
        "Generated mechanically from `baseline_run_26_4_1.json` / harness "
        "comparisons against MESA `26.4.1` reference histories (supplemented "
        "with `log_abs_mdot` / `star_mdot` from cached `mesa-histories-v1` "
        "runs when present). Mass differences are in `Msun`; `log_abs_mdot` "
        "and `lg_mstar_dot_1` differences are in `dex` of "
        "`|Mdot| / (Msun yr^-1)`.",
        "",
        "| Suite | Case | Run Mode | Observed Term | Steps (MESA) | "
        "Mass Col | Mass Final Diff (Msun) | Mass Max Track Diff (Msun) | "
        "mdot Col | mdot Final Diff | mdot Max Track Diff | "
        "mdot Median Track Diff | Declared Gap |",
        "| :--- | :--- | :--- | :--- | ---: | :--- | ---: | ---: | :--- | "
        "---: | ---: | ---: | :--- |",
    ]
    for rec in selected:
        obs_term = (
            f"`{rec.observed_termination}`" if rec.observed_termination else "-"
        )
        gap_str = rec.known_gap_issue if rec.known_gap_issue else "-"
        mass_col, mdot_col = _pick_mass_loss_columns(rec)
        m_fin = (
            rec.comparison.final_diffs.get(mass_col)
            if rec.comparison is not None
            else None
        )
        m_dev = _find_track_dev(rec, mass_col)
        md_fin = (
            rec.comparison.final_diffs.get(mdot_col)
            if rec.comparison is not None
            else None
        )
        md_dev = _find_track_dev(rec, mdot_col)
        md_label = (
            f"`{mdot_col}`"
            if (md_fin is not None or md_dev is not None)
            else "-"
        )
        out.append(
            f"| `{rec.suite}` | `{rec.case}` | {rec.run_mode} | {obs_term} | "
            f"{_fmt_steps_pair(rec)} | `{mass_col}` | "
            f"{_fmt_signed_sci(m_fin)} | "
            f"{_fmt_abs_sci(m_dev.max_abs_diff if m_dev else None)} | "
            f"{md_label} | {_fmt_signed_sci(md_fin)} | "
            f"{_fmt_abs_sci(md_dev.max_abs_diff if md_dev else None)} | "
            f"{_fmt_abs_sci(md_dev.median_abs_diff if md_dev else None)} | "
            f"{gap_str} |"
        )
    return out


def _pick_energy_error_column(
    rec: harness_runner.CaseHarnessRecord,
) -> tuple[history_compare.HistoryComparison, str] | None:
    if rec.comparison is None:
        return None
    comp = rec.comparison
    dev_cols = {d.column for d in comp.track_deviations}
    for cand in history_compare.ENERGY_ERROR_COLUMNS:
        if (
            cand in comp.final_run_values
            or cand in comp.final_ref_values
            or cand in comp.final_diffs
            or cand in dev_cols
        ):
            return comp, cand
    return None


def _fmt_energy_metric(val: float | None, *, is_log: bool) -> str:
    if is_log:
        if val is None:
            return "-"
        if not math.isfinite(val):
            return "non-finite"
        return f"{val:.3f}"
    return _fmt_signed_sci(val)


def _render_energy_conservation_section(
    records: list[harness_runner.CaseHarnessRecord],
) -> list[str]:
    """Render mechanical ``log_rel_run_E_err`` comparisons (#151)."""
    selected: list[
        tuple[
            harness_runner.CaseHarnessRecord,
            history_compare.HistoryComparison,
            str,
        ]
    ] = []
    for rec in records:
        picked = _pick_energy_error_column(rec)
        if picked is not None:
            comp, col = picked
            selected.append((rec, comp, col))
    if not selected:
        return []
    out: list[str] = [
        "",
        "## Energy Conservation Track Comparisons "
        "(`log_rel_run_E_err`, `#151`)",
        "",
        "Generated mechanically from `baseline_run_26_4_1.json` / harness "
        "comparisons against MESA `26.4.1` reference histories (`#151`). "
        "`log_rel_run_E_err` values are `log10(|cumulative_energy_error / "
        "total_energy_end|)` in `dex`.",
        "",
        "| Suite | Case | Run Mode | Observed Term | Steps (MESA) | "
        "Col | FlexMESA Final | MESA 26.4.1 Final | Final Diff | "
        "Max Track Diff | Median Track Diff | Declared Gap |",
        "| :--- | :--- | :--- | :--- | ---: | :--- | ---: | ---: | ---: | "
        "---: | ---: | :--- |",
    ]
    for rec, comp, col in selected:
        obs_term = (
            f"`{rec.observed_termination}`" if rec.observed_termination else "-"
        )
        gap_str = rec.known_gap_issue if rec.known_gap_issue else "-"
        is_log = col.startswith("log_")
        run_fin = comp.final_run_values.get(col)
        ref_fin = comp.final_ref_values.get(col)
        fin_diff = comp.final_diffs.get(col)
        dev = _find_track_dev(rec, col)
        out.append(
            f"| `{rec.suite}` | `{rec.case}` | {rec.run_mode} | {obs_term} | "
            f"{_fmt_steps_pair(rec)} | `{col}` | "
            f"{_fmt_energy_metric(run_fin, is_log=is_log)} | "
            f"{_fmt_energy_metric(ref_fin, is_log=is_log)} | "
            f"{_fmt_signed_sci(fin_diff)} | "
            f"{_fmt_abs_sci(dev.max_abs_diff if dev else None)} | "
            f"{_fmt_abs_sci(dev.median_abs_diff if dev else None)} | "
            f"{gap_str} |"
        )
    return out


def _fmt_final_age_diff(rec: harness_runner.CaseHarnessRecord) -> str:
    if rec.comparison is None:
        return "-"
    xcol = rec.comparison.independent_var
    rel_key = f"rel_{xcol}"
    if rel_key in rec.comparison.final_diffs:
        val = rec.comparison.final_diffs[rel_key]
        if not math.isfinite(val):
            return "non-finite"
        return f"{100.0 * val:+.2f}%"
    if xcol in rec.comparison.final_diffs:
        val = rec.comparison.final_diffs[xcol]
        if not math.isfinite(val):
            return "non-finite"
        return f"{val:+.3e}"
    return "-"


def _render_stage_step_section(
    records: list[harness_runner.CaseHarnessRecord],
) -> list[str]:
    """Render the cases whose stage step counts differ from MESA's.

    The section appears only when a run reported per-stage step counts. A
    passing case in it is a warning, not a change of verdict (``DECISIONS
    #69``). Each stage is ``FlexMESA / MESA`` as the model number reached at
    the end of the stage.
    """
    rows = [r for r in records if r.step_count_differs]
    if not rows:
        return []
    lines = [
        "",
        "## Step counts that differ from MESA",
        "",
        "Model number at the end of each stage, FlexMESA / MESA. A `pass` in "
        "this list is a warning: the trajectory is within tolerance but "
        "takes other steps than MESA.",
        "",
        "| Suite | Case | Verdict | Stages (FlexMESA / MESA) |",
        "| :-- | :-- | :-- | :-- |",
    ]
    for r in rows:
        stages = ", ".join(
            f"{d.run} / {d.mesa if d.mesa is not None else '-'}"
            for d in r.stage_step_deltas
        )
        warn = " (warning)" if r.verdict == "pass" else ""
        lines.append(
            f"| `{r.suite}` | `{r.case}` | {r.verdict}{warn} | {stages} |"
        )
    return lines


def render_case_table_markdown(
    manifest: case_manifest.HarnessManifest,
    records: list[harness_runner.CaseHarnessRecord],
    *,
    summary: dict[str, Any] | None = None,
    known_gaps: dict[tuple[str, str], case_manifest.KnownGapSpec] | None = None,
    figure_links: dict[tuple[str, str], str] | None = None,
    title: str = "Upstream MESA Trajectory Case Table",
) -> str:
    """Render a deterministic Markdown table from ``records``.

    Args:
        manifest: ``HarnessManifest`` instance.
        records: Sequence of ``CaseHarnessRecord`` entries.
        summary: Optional precomputed summary dictionary.
        known_gaps: Optional ``known_gaps.toml`` mapping.
        figure_links: Optional mapping from ``(suite, case)`` to comparison
            figure link targets included as a trailing column when given.
        title: Top-level Markdown heading text.

    Returns:
        Formatted Markdown document ending with a newline.
    """
    head = (
        summary
        if summary is not None
        else summarize_records(manifest, records, known_gaps)
    )
    include_figures = figure_links is not None
    suites = head["cases_by_suite"]
    lines: list[str] = [
        GENERATED_HEADER,
        f"# {title}",
        "",
        "Generated mechanically by `flexmesa harness` from "
        "`benchmarks/history_harness/case_manifest.toml` and "
        "`benchmarks/history_harness/known_gaps.toml` (`#143`).",
        "",
        "## Headline Summary",
        "",
        "| Metric | Count |",
        "| :--- | ---: |",
        (
            f"| Target `v0.1.0` cases (MESA `{head['mesa_release']}`, "
            f"Zenodo `{head['zenodo_record']}`) | "
            f"{head['total_cases']} (`{suites['star']}` star, "
            f"`{suites['binary']}` binary, `{suites['astero']}` astero) |"
        ),
        (
            "| Stored MESA `26.4.1` references (`mesa_26_4_1`) | "
            f"{head['reference_mesa_26_4_1']} |"
        ),
        (
            "| Interim `0b2e6bb` references (`interim_0b2e6bb`, "
            "diagnostic only; never used for acceptance) | "
            f"{head['reference_interim_0b2e6bb']} |"
        ),
        (
            "| Cases awaiting `26.4.1` reference (`no reference yet`) | "
            f"{head['reference_none_yet']} |"
        ),
        f"| Cases selected in this table | {head['selected_cases']} |",
        f"| Cases executed in this run | {head['executed_cases']} |",
        (
            "| Cases accepted by strict control validation (`#147`) | "
            f"{head['strict_validated_cases']} "
            f"({head['strict_cases_taking_steps']} took at least one step) |"
        ),
        (
            "| Cases rejected by strict validation and rerun as diagnostic "
            "(unsupported controls ignored; never a pass) | "
            f"{head['diagnostic_cases']} "
            f"({head['diagnostic_cases_taking_steps']} took at least one "
            "step) |"
        ),
        (
            "| Strict runs reaching upstream termination | "
            f"{head['reaching_upstream_termination']} |"
        ),
        (
            "| Diagnostic runs reaching upstream termination | "
            f"{head['diagnostic_reaching_upstream_termination']} |"
        ),
        (
            "| Acceptance passes against MESA `26.4.1` (`pass`) | "
            f"{head['passing_mesa_26_4_1']} |"
        ),
        (
            "| Interim `0b2e6bb` comparisons within manifest tolerance | "
            f"{head['interim_within_tolerance']} |"
        ),
        (
            "| Declared known gaps (`known_gaps.toml`) | "
            f"{head['declared_known_gaps']} |"
        ),
        f"| Undeclared failures | {len(head['undeclared_failures'])} |",
        "",
        "## Per-Case Status and Reference Availability",
        "",
        "`Run Mode` says which run the measured columns come from. `strict` "
        "is a run that passed strict control validation (`#147`). "
        "`diagnostic (N controls ignored)` means strict validation stopped "
        "the case on `N` unsupported controls in the first stage inlist "
        "that sets any, and the case was rerun with unsupported controls "
        "ignored. A diagnostic run did not do what the inlist asks, so its "
        "numbers show where the engine stands and can never give a `pass`. "
        "`Steps (MESA)` and `Retries (MESA)` report FlexMESA final-stage "
        "steps and cumulative retries followed in parentheses by the stored "
        "MESA `26.4.1` reference counts (`#152`). `Iters (MESA)` reports mean "
        "Newton solver iterations per logged step with cumulative sum "
        "`[total]` for FlexMESA (logged every step) followed in parentheses "
        "by MESA `26.4.1` mean iterations per logged row with `[total]` when "
        "every step was logged or `[sum/Nr]` when MESA logged `N` rows at "
        "`history_interval > 1`. `Peak RSS` reports the peak worker resident "
        "set size (`GB` in `10^6`-KiB units; `-` in normalized deterministic "
        "baselines or unexecuted cases). `num_zones Track Diff` reports the "
        "maximum along-track relative and absolute zone-count deviation "
        "`rel% (abs)` against MESA `26.4.1` (`#153`, `DECISIONS #44`).",
        "",
        "| Suite | Case | Reference Status | Required Termination | "
        "Run Mode | Observed Term | Steps (MESA) | Retries (MESA) | "
        "Iters (MESA) | Peak RSS | num_zones Track Diff | Final Coord Diff | "
        "Max Track Diff | First Div Step | Declared Gap | Verdict |"
        + (" Figure |" if include_figures else ""),
        "| :--- | :--- | :--- | :--- | :--- | :--- | ---: | ---: | ---: | "
        "---: | ---: | ---: | :--- | ---: | :--- | :--- |"
        + (" :--- |" if include_figures else ""),
    ]

    for rec in records:
        obs_term = (
            f"`{rec.observed_termination}`" if rec.observed_termination else "-"
        )
        first_div = (
            str(rec.comparison.first_diverging_step)
            if rec.comparison is not None
            and rec.comparison.first_diverging_step is not None
            else "-"
        )
        gap_str = rec.known_gap_issue if rec.known_gap_issue else "-"
        fig_cell = ""
        if include_figures:
            assert figure_links is not None
            fig_target = figure_links.get((rec.suite, rec.case))
            fig_cell = f" [compare]({fig_target}) |" if fig_target else " - |"
        lines.append(
            f"| `{rec.suite}` | `{rec.case}` | `{rec.reference_status}` | "
            f"`{rec.required_termination}` | {rec.run_mode} | {obs_term} | "
            f"{_fmt_steps_pair(rec)} | {_fmt_retries_pair(rec)} | "
            f"{_fmt_iters_pair(rec)} | {_fmt_peak_rss(rec)} | "
            f"{_fmt_num_zones_diff(rec)} | "
            f"{_fmt_final_age_diff(rec)} | {_fmt_max_dev(rec)} | "
            f"{first_div} | {gap_str} | {rec.verdict} |"
            f"{fig_cell}"
        )

    lines.extend(_render_convective_core_section(manifest, records))
    lines.extend(_render_mass_loss_section(records))
    lines.extend(_render_search_track_section(records))
    lines.extend(_render_energy_conservation_section(records))
    lines.extend(_render_stage_step_section(records))
    lines.append("")
    return "\n".join(lines)


def build_manifest_inventory_records(
    manifest_path: pathlib.Path | str | None = None,
    known_gaps_path: pathlib.Path | str | None = None,
    baseline_json_path: pathlib.Path | str | None = None,
) -> tuple[
    case_manifest.HarnessManifest,
    dict[tuple[str, str], case_manifest.KnownGapSpec],
    list[harness_runner.CaseHarnessRecord],
]:
    """Build ``CaseHarnessRecord`` entries from manifest and baseline JSON.

    Re-evaluates verdicts dynamically against ``case_manifest.toml`` and
    ``known_gaps.toml`` using stored MESA ``26.4.1`` baseline measurements when
    present, judging stage step counts as ``DECISIONS #70`` requires (the
    committed baseline is a step-count-enforced snapshot).

    Args:
        manifest_path: Optional path to ``case_manifest.toml``.
        known_gaps_path: Optional path to ``known_gaps.toml``.
        baseline_json_path: Optional path to ``baseline_run_26_4_1.json``.

    Returns:
        Tuple ``(manifest, known_gaps, records)`` across all manifest entries.
    """
    manifest = case_manifest.load_case_manifest(manifest_path)
    gaps = case_manifest.load_known_gaps(known_gaps_path)

    resolved_baseline: pathlib.Path | None = None
    if baseline_json_path is not None:
        resolved_baseline = pathlib.Path(baseline_json_path)
        if not resolved_baseline.is_file():
            raise FileNotFoundError(
                f"missing baseline JSON: {resolved_baseline}"
            )
    elif (
        manifest_path is None
        or pathlib.Path(manifest_path).resolve()
        == case_manifest.default_manifest_path().resolve()
    ):
        cand = default_baseline_json_path()
        if cand.is_file():
            resolved_baseline = cand

    stored_by_key: dict[tuple[str, str], dict[str, Any]] = {}
    if resolved_baseline is not None and resolved_baseline.is_file():
        raw_payload = json.loads(resolved_baseline.read_text(encoding="utf-8"))
        for item in raw_payload.get("cases", ()):
            if item.get("executed"):
                stored_by_key[(str(item["suite"]), str(item["case"]))] = item

    base_dir = (
        pathlib.Path(manifest_path).parent
        if manifest_path is not None
        else None
    )
    records = records_from_stored_rows(
        manifest,
        gaps,
        stored_by_key,
        base_dir,
        enforce_step_counts=True,
    )
    return manifest, gaps, records


def records_from_stored_rows(
    manifest: case_manifest.HarnessManifest,
    gaps: dict[tuple[str, str], case_manifest.KnownGapSpec],
    stored_by_key: dict[tuple[str, str], dict[str, Any]],
    base_dir: pathlib.Path | None = None,
    *,
    max_steps: int | None = None,
    enforce_step_counts: bool = False,
) -> list[harness_runner.CaseHarnessRecord]:
    """Rebuild ``CaseHarnessRecord`` entries from stored JSON case rows.

    Verdicts are re-evaluated against ``manifest`` and ``gaps`` from the
    stored measurements and comparisons; no history file is read.

    Args:
        manifest: Loaded ``HarnessManifest``.
        gaps: Loaded ``known_gaps.toml`` mapping.
        stored_by_key: Executed case rows (as written by
            :func:`record_to_dict`) keyed by ``(suite, case)``.
        base_dir: Directory against which manifest reference paths resolve.
        max_steps: Step cap the stored runs used, or ``None`` when uncapped.
        enforce_step_counts: Judge stored stage step counts as ``DECISIONS
            #70`` requires (see ``evaluate_case_record``).

    Returns:
        One record per manifest entry, in manifest order; entries without a
        stored row are not-executed records.
    """
    records: list[harness_runner.CaseHarnessRecord] = []
    for entry in manifest.cases:
        stored = stored_by_key.get(entry.key)
        if stored is None:
            records.append(
                harness_runner.evaluate_case_record(
                    entry, gaps, None, max_steps=max_steps, root_dir=base_dir
                )
            )
            continue
        raw_iters = stored.get("iters")
        raw_mean_iters = stored.get("mean_iters")
        outcome = harness_runner.TraceRunOutcome(
            suite=entry.suite,
            case=entry.case,
            status=str(stored.get("run_status", "error")),
            termination_code=str(stored.get("observed_termination", "")),
            steps=int(stored.get("steps", 0)),
            retries=int(stored.get("retries", 0)),
            wall_time_sec=float(stored.get("wall_time_sec", 0.0)),
            peak_rss_gb=float(stored.get("peak_rss_gb", 0.0)),
            history_path=None,
            error_message=str(stored.get("error_message", "")),
            controls_ignored=bool(stored.get("controls_ignored", False)),
            n_controls_ignored=int(stored.get("n_controls_ignored", 0)),
            strict_rejection=str(stored.get("strict_rejection", "")),
            stage_steps=tuple(int(n) for n in stored.get("stage_steps", ())),
            iters=int(raw_iters) if raw_iters is not None else None,
            mean_iters=(
                float(raw_mean_iters) if raw_mean_iters is not None else None
            ),
        )
        has_mesa_meta = any(
            k in stored for k in ("mesa_steps", "mesa_retries", "mesa_iters")
        )
        pre_mesa = (
            history_compare.HistoryRunStats(
                steps=(
                    int(stored["mesa_steps"])
                    if stored.get("mesa_steps") is not None
                    else None
                ),
                retries=(
                    int(stored["mesa_retries"])
                    if stored.get("mesa_retries") is not None
                    else None
                ),
                iters_sum=(
                    int(stored["mesa_iters"])
                    if stored.get("mesa_iters") is not None
                    else None
                ),
                mean_iters=(
                    float(stored["mesa_mean_iters"])
                    if stored.get("mesa_mean_iters") is not None
                    else None
                ),
                iters_rows=int(stored.get("mesa_iters_rows", 0)),
            )
            if has_mesa_meta
            else None
        )
        raw_comp = stored.get("comparison")
        comp = (
            history_compare.comparison_from_dict(raw_comp)
            if isinstance(raw_comp, dict)
            else None
        )
        raw_art = stored.get("artifact_comparison")
        raw_ccomps = stored.get("component_comparisons")
        ccomps = (
            {
                str(cname): history_compare.comparison_from_dict(cval)
                for cname, cval in raw_ccomps.items()
                if isinstance(cval, dict)
            }
            if isinstance(raw_ccomps, dict)
            else None
        )
        records.append(
            harness_runner.evaluate_case_record(
                entry,
                gaps,
                outcome,
                max_steps=max_steps,
                root_dir=base_dir,
                precomputed_comparison=comp,
                precomputed_component_comparisons=ccomps,
                precomputed_has_component_error=bool(
                    stored.get("has_component_error", False)
                ),
                precomputed_mesa_stats=pre_mesa,
                enforce_step_counts=enforce_step_counts,
                artifact_comparison=(
                    artifact_compare.comparison_from_dict(raw_art)
                    if isinstance(raw_art, dict)
                    else None
                ),
            )
        )
    return records
